import torch
import torch.nn as nn
import hashlib
from torch.utils.cpp_extension import load_inline

_STARK_EXTENSION = None

def _stark_strip_anchor_markers(source: str) -> str:
    cleaned_lines = []
    for line in source.splitlines():
        stripped = line.lstrip()
        if stripped.startswith('# <<<IMPROVE:') or stripped.startswith('# <<<END_IMPROVE>>>'):
            continue
        cleaned_lines.append(line)
    return '\n'.join(cleaned_lines)

def _stark_extension_name() -> str:
    digest = hashlib.sha1((_stark_strip_anchor_markers(CUDA_CPP_SRC) + _stark_strip_anchor_markers(CUDA_CU_SRC)).encode('utf-8')).hexdigest()[:12]
    return f'stark_cuda_l2_p77_{digest}'

def _stark_get_extension():
    global _STARK_EXTENSION
    if _STARK_EXTENSION is None:
        _STARK_EXTENSION = load_inline(
            name=_stark_extension_name(),
            cpp_sources=_stark_strip_anchor_markers(CUDA_CPP_SRC),
            cuda_sources=_stark_strip_anchor_markers(CUDA_CU_SRC),
            functions=None,
            extra_cflags=['-O3'],
            extra_cuda_cflags=['-O3', '--use_fast_math'],
            with_cuda=True,
            verbose=False,
        )
    return _STARK_EXTENSION

# <<<IMPROVE:user_helpers>>>
# <<<END_IMPROVE>>>

CUDA_CPP_SRC = r"""
# <<<IMPROVE:cuda_cpp>>>
#include <torch/extension.h>

torch::Tensor fused_scale_bn_globalavgpool_cuda(
    torch::Tensor input,
    float scale_factor,
    torch::Tensor bn_weight,
    torch::Tensor bn_bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    float eps,
    float momentum,
    bool training
);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("fused_scale_bn_globalavgpool",
          &fused_scale_bn_globalavgpool_cuda,
          "Fused scale + batch norm + global avg pool (CUDA)");
}
# <<<END_IMPROVE>>>
"""

CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// Fused kernel: for each (n, c) block, compute scaled BN stats + affine + global avg pool.
// Grid: (N, C), Block: up to 256 threads covering DHW elements.
// Training mode: compute batch statistics over N*D*H*W per channel.
// Eval mode: use running_mean/running_var.

// Two-pass approach for training:
// Pass 1: each block reduces over its (n,c) slice -> partial sums stored in global arrays
// Then a second kernel reduces across N for per-channel mean/var
// Pass 3: each block normalizes and accumulates global avg

// For simplicity and correctness, we use a single-kernel approach with atomics for training stats.

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// Kernel 1 (training): compute per-channel sum and sum-of-squares over N*D*H*W (after scaling)
// grid: (C, gridDim_spatial) where each block covers a chunk of N*D*H*W
__global__ void compute_stats_kernel(
    const float* __restrict__ input,
    float scale_factor,
    float* __restrict__ sum_out,    // [C]
    float* __restrict__ sumsq_out,  // [C]
    int N, int C, int D, int H, int W
) {
    int c = blockIdx.x;
    int DHW = D * H * W;
    int total = N * DHW;

    float local_sum = 0.f;
    float local_sumsq = 0.f;

    for (int idx = threadIdx.x + blockIdx.y * blockDim.x; idx < total; idx += blockDim.x * gridDim.y) {
        int n = idx / DHW;
        int dhw = idx % DHW;
        float val = input[n * C * DHW + c * DHW + dhw] * scale_factor;
        local_sum += val;
        local_sumsq += val * val;
    }

    // warp reduce
    local_sum = warp_reduce_sum(local_sum);
    local_sumsq = warp_reduce_sum(local_sumsq);

    __shared__ float smem_sum[32];
    __shared__ float smem_sumsq[32];
    int lane = threadIdx.x & 31;
    int wid = threadIdx.x >> 5;
    if (lane == 0) {
        smem_sum[wid] = local_sum;
        smem_sumsq[wid] = local_sumsq;
    }
    __syncthreads();

    int nwarps = (blockDim.x + 31) / 32;
    if (threadIdx.x < nwarps) {
        local_sum = smem_sum[threadIdx.x];
        local_sumsq = smem_sumsq[threadIdx.x];
    } else {
        local_sum = 0.f;
        local_sumsq = 0.f;
    }
    if (wid == 0) {
        local_sum = warp_reduce_sum(local_sum);
        local_sumsq = warp_reduce_sum(local_sumsq);
    }

    if (threadIdx.x == 0) {
        atomicAdd(&sum_out[c], local_sum);
        atomicAdd(&sumsq_out[c], local_sumsq);
    }
}

// Kernel 2 (training + eval): given mean/inv_std per channel, compute:
//   scaled_val = input * scale_factor
//   normed = (scaled_val - mean) * inv_std
//   affine = gamma * normed + beta
//   accumulate affine into global sum for avg pool
__global__ void normalize_and_pool_kernel(
    const float* __restrict__ input,
    float scale_factor,
    const float* __restrict__ mean,     // [C]
    const float* __restrict__ inv_std,  // [C]
    const float* __restrict__ gamma,    // [C]
    const float* __restrict__ beta,     // [C]
    float* __restrict__ out,            // [N, C, 1, 1, 1]
    int N, int C, int D, int H, int W
) {
    int c = blockIdx.x;
    int n = blockIdx.y;
    int DHW = D * H * W;

    float m = mean[c];
    float is_ = inv_std[c];
    float g = gamma[c];
    float b = beta[c];

    float local_sum = 0.f;
    for (int dhw = threadIdx.x; dhw < DHW; dhw += blockDim.x) {
        float val = input[n * C * DHW + c * DHW + dhw] * scale_factor;
        float normed = (val - m) * is_;
        local_sum += g * normed + b;
    }

    local_sum = warp_reduce_sum(local_sum);
    __shared__ float smem[32];
    int lane = threadIdx.x & 31;
    int wid = threadIdx.x >> 5;
    if (lane == 0) smem[wid] = local_sum;
    __syncthreads();
    int nwarps = (blockDim.x + 31) / 32;
    if (threadIdx.x < nwarps) local_sum = smem[threadIdx.x]; else local_sum = 0.f;
    if (wid == 0) local_sum = warp_reduce_sum(local_sum);

    if (threadIdx.x == 0) {
        out[n * C + c] = local_sum / (float)DHW;
    }
}

torch::Tensor fused_scale_bn_globalavgpool_cuda(
    torch::Tensor input,          // [N, C, D, H, W] contiguous float32
    float scale_factor,
    torch::Tensor bn_weight,      // [C] gamma
    torch::Tensor bn_bias,        // [C] beta
    torch::Tensor running_mean,   // [C]
    torch::Tensor running_var,    // [C]
    float eps,
    float momentum,
    bool training
) {
    input = input.contiguous();
    int N = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);
    int DHW = D * H * W;
    int total = N * DHW;

    auto opts = torch::TensorOptions().dtype(torch::kFloat32).device(input.device());
    auto out = torch::empty({N, C, 1, 1, 1}, opts);

    auto mean_t = torch::empty({C}, opts);
    auto inv_std_t = torch::empty({C}, opts);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    if (training) {
        // Compute per-channel mean and variance over N*D*H*W
        auto sum_t = torch::zeros({C}, opts);
        auto sumsq_t = torch::zeros({C}, opts);

        int block_size = 256;
        int grid_y = (total + block_size - 1) / block_size;
        grid_y = min(grid_y, 64);
        dim3 grid(C, grid_y);
        compute_stats_kernel<<<grid, block_size, 0, stream>>>(
            input.data_ptr<float>(),
            scale_factor,
            sum_t.data_ptr<float>(),
            sumsq_t.data_ptr<float>(),
            N, C, D, H, W
        );

        float n_elements = (float)(N * DHW);
        // mean = sum / n, var = sumsq/n - mean^2
        mean_t = sum_t / n_elements;
        auto var_t = sumsq_t / n_elements - mean_t * mean_t;
        inv_std_t = torch::rsqrt(var_t + eps);

        // Update running stats
        running_mean.mul_(1.0f - momentum).add_(mean_t * momentum);
        running_var.mul_(1.0f - momentum).add_(var_t * momentum);
    } else {
        mean_t = running_mean.to(opts.dtype());
        inv_std_t = torch::rsqrt(running_var.to(opts.dtype()) + eps);
    }

    // Normalize, apply affine, and pool
    int block_size2 = 256;
    dim3 grid2(C, N);
    normalize_and_pool_kernel<<<grid2, block_size2, 0, stream>>>(
        input.data_ptr<float>(),
        scale_factor,
        mean_t.data_ptr<float>(),
        inv_std_t.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, D, H, W
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a 3D transposed convolution, scales the output, applies batch normalization, 
        and then performs global average pooling. 
        """
    def __init__(self, in_channels, out_channels, kernel_size, scale_factor, eps=1e-5, momentum=0.1):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size)
        self.scale_factor = scale_factor
        self.batch_norm = nn.BatchNorm3d(out_channels, eps=eps, momentum=momentum)
        self.global_avg_pool = nn.AdaptiveAvgPool3d((1, 1, 1))
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        x = self.conv_transpose(x)
        if x.is_cuda and x.dtype == torch.float32:
            x = _stark_get_extension().fused_scale_bn_globalavgpool(
                x,
                float(self.scale_factor),
                self.batch_norm.weight,
                self.batch_norm.bias,
                self.batch_norm.running_mean,
                self.batch_norm.running_var,
                float(self.batch_norm.eps),
                float(self.batch_norm.momentum),
                self.batch_norm.training,
            )
            return x
        else:
            x = x * self.scale_factor
            x = self.batch_norm(x)
            x = self.global_avg_pool(x)
            return x
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_2>>>
        # scale fused into CUDA kernel above; fallback handled in forward_stmt_1
        pass
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_3>>>
        # batch norm fused into CUDA kernel above; fallback handled in forward_stmt_1
        pass
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_4>>>
        # global avg pool fused into CUDA kernel above; fallback handled in forward_stmt_1
        pass
        # <<<END_IMPROVE>>>
        # <<<IMPROVE:forward_stmt_5>>>
        return x
        # <<<END_IMPROVE>>>

