CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

__device__ __forceinline__ float warp_reduce_sum(float val) {
    for (int offset = 16; offset > 0; offset >>= 1)
        val += __shfl_down_sync(0xffffffff, val, offset);
    return val;
}

// Kernel 1: compute per-channel sum, sumsq over N*D*H*W AND per-(n,c) sum
// grid: (C, grid_y) where grid_y tiles over N*DHW
// nc_sum_out: [N, C] - sum of scaled values per (n,c) slice
// sum_out: [C] - sum over all N*D*H*W per channel
// sumsq_out: [C] - sum of squares over all N*D*H*W per channel
__global__ void compute_stats_and_nc_sum_kernel(
    const float* __restrict__ input,
    float scale_factor,
    float* __restrict__ nc_sum_out,  // [N, C]
    float* __restrict__ sum_out,     // [C]
    float* __restrict__ sumsq_out,   // [C]
    int N, int C, int D, int H, int W
) {
    int c = blockIdx.x;
    int DHW = D * H * W;
    int total = N * DHW;

    float local_sum = 0.f;
    float local_sumsq = 0.f;

    // Also accumulate per-(n,c) sums using shared memory per n
    // Strategy: each thread accumulates its own nc contributions
    // We use atomics into nc_sum_out for simplicity (N is small relative to DHW)
    for (int idx = threadIdx.x + blockIdx.y * blockDim.x; idx < total; idx += blockDim.x * gridDim.y) {
        int n = idx / DHW;
        int dhw = idx % DHW;
        float val = input[n * C * DHW + c * DHW + dhw] * scale_factor;
        local_sum += val;
        local_sumsq += val * val;
        atomicAdd(&nc_sum_out[n * C + c], val);
    }

    // Block reduce for channel-level stats
    local_sum = warp_reduce_sum(local_sum);
    local_sumsq = warp_reduce_sum(local_sumsq);

    __shared__ float smem_sum[32];
    __shared__ float smem_sumsq[32];
    int lane = threadIdx.x & 31;
    int wid = threadIdx.x >> 5;
    if (lane == 0) {
        smem_sum[wid] = local_sum;
        smem_sumsq[wid] = local_sumsq;
    }
    __syncthreads();

    int nwarps = (blockDim.x + 31) / 32;
    if (threadIdx.x < nwarps) {
        local_sum = smem_sum[threadIdx.x];
        local_sumsq = smem_sumsq[threadIdx.x];
    } else {
        local_sum = 0.f;
        local_sumsq = 0.f;
    }
    if (wid == 0) {
        local_sum = warp_reduce_sum(local_sum);
        local_sumsq = warp_reduce_sum(local_sumsq);
    }

    if (threadIdx.x == 0) {
        atomicAdd(&sum_out[c], local_sum);
        atomicAdd(&sumsq_out[c], local_sumsq);
    }
}

// Kernel for eval: compute per-(n,c) sum only (no stats needed)
__global__ void compute_nc_sum_kernel(
    const float* __restrict__ input,
    float scale_factor,
    float* __restrict__ nc_sum_out,  // [N, C]
    int N, int C, int D, int H, int W
) {
    int c = blockIdx.x;
    int n = blockIdx.y;
    int DHW = D * H * W;

    float local_sum = 0.f;
    for (int dhw = threadIdx.x; dhw < DHW; dhw += blockDim.x) {
        float val = input[n * C * DHW + c * DHW + dhw] * scale_factor;
        local_sum += val;
    }

    local_sum = warp_reduce_sum(local_sum);
    __shared__ float smem[32];
    int lane = threadIdx.x & 31;
    int wid = threadIdx.x >> 5;
    if (lane == 0) smem[wid] = local_sum;
    __syncthreads();
    int nwarps = (blockDim.x + 31) / 32;
    if (threadIdx.x < nwarps) local_sum = smem[threadIdx.x]; else local_sum = 0.f;
    if (wid == 0) local_sum = warp_reduce_sum(local_sum);

    if (threadIdx.x == 0) {
        nc_sum_out[n * C + c] = local_sum;
    }
}

// Kernel: compute final output from per-(n,c) sums and per-channel stats
// out[n,c] = gamma[c] * ((nc_mean[n,c] - mean[c]) * inv_std[c]) + beta[c]
// where nc_mean[n,c] = nc_sum[n,c] / DHW
__global__ void compute_output_from_sums_kernel(
    const float* __restrict__ nc_sum,   // [N, C]
    const float* __restrict__ mean,     // [C]
    const float* __restrict__ inv_std,  // [C]
    const float* __restrict__ gamma,    // [C]
    const float* __restrict__ beta,     // [C]
    float* __restrict__ out,            // [N*C] -> view as [N,C,1,1,1]
    int N, int C, float inv_DHW
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * C;
    if (idx >= total) return;
    int n = idx / C;
    int c = idx % C;
    float nc_mean = nc_sum[n * C + c] * inv_DHW;
    float normed = (nc_mean - mean[c]) * inv_std[c];
    out[idx] = gamma[c] * normed + beta[c];
}

torch::Tensor fused_scale_bn_globalavgpool_cuda(
    torch::Tensor input,          // [N, C, D, H, W] contiguous float32
    float scale_factor,
    torch::Tensor bn_weight,      // [C] gamma
    torch::Tensor bn_bias,        // [C] beta
    torch::Tensor running_mean,   // [C]
    torch::Tensor running_var,    // [C]
    float eps,
    float momentum,
    bool training
) {
    input = input.contiguous();
    int N = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);
    int DHW = D * H * W;
    int total = N * DHW;
    float inv_DHW = 1.0f / (float)DHW;

    auto opts = torch::TensorOptions().dtype(torch::kFloat32).device(input.device());
    auto out = torch::empty({N, C, 1, 1, 1}, opts);
    auto nc_sum_t = torch::zeros({N, C}, opts);

    auto mean_t = torch::empty({C}, opts);
    auto inv_std_t = torch::empty({C}, opts);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    if (training) {
        auto sum_t = torch::zeros({C}, opts);
        auto sumsq_t = torch::zeros({C}, opts);

        int block_size = 256;
        int grid_y = (total + block_size - 1) / block_size;
        grid_y = min(grid_y, 64);
        dim3 grid(C, grid_y);
        compute_stats_and_nc_sum_kernel<<<grid, block_size, 0, stream>>>(
            input.data_ptr<float>(),
            scale_factor,
            nc_sum_t.data_ptr<float>(),
            sum_t.data_ptr<float>(),
            sumsq_t.data_ptr<float>(),
            N, C, D, H, W
        );

        float n_elements = (float)(N * DHW);
        mean_t = sum_t / n_elements;
        auto var_t = sumsq_t / n_elements - mean_t * mean_t;
        inv_std_t = torch::rsqrt(var_t + eps);

        // Update running stats
        running_mean.mul_(1.0f - momentum).add_(mean_t * momentum);
        running_var.mul_(1.0f - momentum).add_(var_t * momentum);
    } else {
        // Eval: just compute per-(n,c) sums
        int block_size = 256;
        dim3 grid(C, N);
        compute_nc_sum_kernel<<<grid, block_size, 0, stream>>>(
            input.data_ptr<float>(),
            scale_factor,
            nc_sum_t.data_ptr<float>(),
            N, C, D, H, W
        );
        mean_t = running_mean.to(opts.dtype());
        inv_std_t = torch::rsqrt(running_var.to(opts.dtype()) + eps);
    }

    // Compute final output algebraically from nc sums and channel stats
    int nc_total = N * C;
    int block3 = 256;
    int grid3 = (nc_total + block3 - 1) / block3;
    compute_output_from_sums_kernel<<<grid3, block3, 0, stream>>>(
        nc_sum_t.data_ptr<float>(),
        mean_t.data_ptr<float>(),
        inv_std_t.data_ptr<float>(),
        bn_weight.data_ptr<float>(),
        bn_bias.data_ptr<float>(),
        out.data_ptr<float>(),
        N, C, inv_DHW
    );

    return out;
}
# <<<END_IMPROVE>>>
"""

class ModelNew(nn.Module):
    """
        Model that performs a 3D transposed convolution, scales the output, applies batch normalization, 
        and then performs global average pooling. 
        """
    def __init__(self, in_channels, out_channels, kernel_size, scale_factor, eps=1e-5, momentum=0.1):
        super().__init__()
        # <<<IMPROVE:init_body>>>
        self.conv_transpose = nn.ConvTranspose3d(in_channels, out_channels, kernel_size)
        self.scale_factor = scale_factor
        self.batch_norm = nn.BatchNorm3d(out_channels, eps=eps, momentum=momentum)
        self.global_avg_pool = nn.AdaptiveAvgPool3d((1, 1, 1))
        # <<<END_IMPROVE>>>

    def forward(self, x):
        # <<<IMPROVE:forward_stmt_1>>>
        x = self.conv_transpose(x)
        if x.is_cuda and x.dtype == torch.float32:
            x = _stark_get_extension().fused_scale_bn_globalavgpool(
                x,
                float(self.scale_factor),
                self.batch_norm.weight,
                self.batch_norm.bias,
                self.batch_norm.running_mean,
                self.batch_norm.running_var,
                float(self.batch_norm.eps),
                float(self.batch_norm.momentum),
                self.batch_norm.training,
            )
            return x
        else:
